(()=>{ /* 🂡 MORE CARD GAMES, part 4 (v226): Pitch, Nest Bid (KAN-IN's own bid-for-trump game with its own coloured deck), Pinochle
   (two-handed), Canasta, Hand and Foot, Spit and Nertz, each against computer players. Traditional public-domain rules. */
 const G=window.GAMES; if(!G||!G.reg||!G.lib) return; const L=G.lib, h=L.h, SU=L.SU, VS=L.VS||'', rl=L.rl, cardEl=L.cardEl, shuffle=L.shuffle; const CAT='Cards';
 const OPT=(ctx,id,defs)=>window.KGOPT?KGOPT.row(ctx,id,defs):Object.fromEntries(defs.map(d=>[d[0],d[3]]));
 const beep=(f,d)=>{ try{ L.beep(f,d||.04); }catch(_){ } }; const rnd=n=>Math.floor(Math.random()*n);
 const NM=['You','Nova','Orion','Vega','Lyra','Atlas']; const red=c=>c.s===1||c.s===2; const cn=c=>c.j?'Joker':rl(c.r)+SU[c.s]+VS;
 const cw=(ctx,n,max)=>Math.max(28,Math.min(max||60,Math.floor((((ctx.W&&ctx.W())||360)-12)/Math.max(1,n))-4));
 const bar=root=>{ const b=h('div',{className:'k4Bar'}); root.appendChild(b); return b; };
 const btn=(b,l,f,c)=>{ const e=h('button',{type:'button',className:c||''},l); e.addEventListener('click',f); b.appendChild(e); return e; };
 const jk=(w,cls)=>h('div',{className:'gcard c_jk'+(cls?' '+cls:''),style:'width:'+w+'px;height:'+Math.round(w*1.4)+'px;display:flex;align-items:center;justify-content:center;font-size:'+Math.round(w*.5)+'px'},'🃏');
 const cEl=(c,w,cls)=>c.j?jk(w,cls):cardEl(c,w,false,cls||'');
 const backs=(n,w)=>{ const r=h('div',{className:'k4Hand'}); for(let k=0;k<Math.min(n,7);k++) r.appendChild(cardEl({r:2,s:0},w,true)); if(n>7) r.appendChild(h('span',null,'+'+(n-7))); return r; };
 const css=document.createElement('style'); css.textContent=`
#gamesDock .k5Trick{display:grid;grid-template-columns:repeat(3,auto);gap:4px;justify-content:center;align-items:center;min-height:110px;margin:6px auto}
#gamesDock .k5Trick .t0{grid-area:3/2}#gamesDock .k5Trick .t1{grid-area:2/1}#gamesDock .k5Trick .t2{grid-area:1/2}#gamesDock .k5Trick .t3{grid-area:2/3}#gamesDock .k5Trick .tc{grid-area:2/2;color:#ffe94a;font:800 12px system-ui;text-align:center;max-width:90px}
#gamesDock .nb{display:inline-flex;align-items:center;justify-content:center;flex-direction:column;border-radius:9px;border:3px solid #fff;color:#fff;font:900 calc(var(--w)*.42)/1 system-ui;width:var(--w);height:calc(var(--w)*1.4);cursor:pointer;box-shadow:0 2px 4px rgba(0,0,0,.5)}
#gamesDock .nb.k0{background:#d83434}#gamesDock .nb.k1{background:#2f6be0}#gamesDock .nb.k2{background:#1f9a4d}#gamesDock .nb.k3{background:#e2a614}#gamesDock .nb.bird{background:radial-gradient(circle,#fff 0 30%,#222 31%);font-size:calc(var(--w)*.5)}
#gamesDock .nb.back{background:repeating-linear-gradient(45deg,#2a145c 0 6px,#3b1f7a 6px 12px)}#gamesDock .nb.sel{transform:translateY(-8px);box-shadow:0 0 0 3px #ffe94a}#gamesDock .nb.play{box-shadow:0 0 0 3px #7cff8a}
#gamesDock .nb small{font-size:40%;opacity:.9}`; document.head.appendChild(css);

 /* ───────── PITCH (four players, partners) ───────── */
 G.reg('c_pitch','Pitch',CAT,'An American trick-taking classic for four, in partnerships: you and Orion against Nova and Vega. Six cards each. Bid 2, 3 or 4 (or pass) for the points you think your side can take; the dealer must bid if everyone passes. The high bidder leads, and the suit of the first card led is trumps. Follow the suit led if you can, or play a trump at any time. Four points are out each hand: High (the highest trump played), Low (the lowest trump played), Jack (whoever wins the jack of trumps) and Game (most of 10s=10, aces=4, kings=3, queens=2, jacks=1 in the tricks you take). If the bidders fall short they lose their bid. First side to the target wins.',ctx=>{
  const O=OPT(ctx,'c_pitch',[['to','Play to',[[7,'7'],[11,'11 (standard)'],[15,'15'],[21,'21'],[31,'31']],11],['stuck','If everyone passes',[['dealer','Dealer must bid 2'],['redeal','Deal again'],['dealer3','Dealer must bid 3'],['low','Lowest hand bids 2'],['first','First player bids 2']],'dealer']]);
  const team=p=>p%2; const st={hands:[],bids:[],bid:0,bidder:-1,trump:null,trick:[],lead:0,turn:0,won:[[],[]],played:[],score:[0,0],dealer:3,phase:'bid',msg:'',over:false};
  const root=h('div',{className:'k4'}); ctx.area.appendChild(root); const R=c=>c.r===1?14:c.r; const gp=c=>c.r===10?10:c.r===1?4:c.r===13?3:c.r===12?2:c.r===11?1:0;
  function deal(){ const d=shuffle(L.mkDeck(true)); st.hands=[0,1,2,3].map(()=>d.splice(0,6)); st.dealer=(st.dealer+1)%4; st.bids=[]; st.bid=0; st.bidder=-1; st.trump=null; st.trick=[]; st.won=[[],[]]; st.played=[]; st.phase='bid'; st.turn=(st.dealer+1)%4; st.msg='Bidding: '+(st.turn?NM[st.turn]+' bids first.':'you bid first.'); render(); if(st.turn) ctx.after(700,aiBid); }
  const strength=hd=>{ let best=0; for(let s=0;s<4;s++){ const t=hd.filter(c=>c.s===s); let v=t.length*0.4; if(t.some(c=>c.r===1)) v+=1; if(t.some(c=>c.r===11)) v+=0.6; if(t.some(c=>c.r===2||c.r===3)) v+=0.6; if(t.some(c=>c.r===13)) v+=0.4; best=Math.max(best,v); } return best; };
  function placeBid(p,b){ st.bids[p]=b; if(b>st.bid){ st.bid=b; st.bidder=p; } st.msg=(p?NM[p]:'You')+(b?' bid '+b:' pass')+'. '; const nxt=(p+1)%4; if(p===st.dealer){ if(st.bidder<0){ if(O.stuck==='redeal'){ st.msg+='Everyone passed: new deal.'; render(); return ctx.after(900,deal); } const who=O.stuck==='first'?(st.dealer+1)%4:O.stuck==='low'?[0,1,2,3].sort((a,b)=>strength(st.hands[a])-strength(st.hands[b]))[0]:st.dealer; st.bid=O.stuck==='dealer3'?3:2; st.bidder=who; st.msg+=(who?NM[who]:'You')+' must bid '+st.bid+'. '; } st.phase='play'; st.turn=st.lead=st.bidder; st.msg+=(st.bidder?NM[st.bidder]+' leads and names trumps.':'You lead: your first card sets trumps.'); render(); if(st.turn) ctx.after(800,ai); return; } st.turn=nxt; render(); if(st.turn) ctx.after(600,aiBid); }
  function aiBid(){ if(st.phase!=='bid'||!st.turn) return; const p=st.turn, s=strength(st.hands[p]); let b=s>=3.2?4:s>=2.4?3:s>=1.8?2:0; if(b<=st.bid) b=0; placeBid(p,b); }
  function legal(p){ const hd=st.hands[p]; if(!st.trick.length) return hd; const led=st.trick[0].c.s; const f=hd.filter(c=>c.s===led); return f.length?hd.filter(c=>c.s===led||c.s===st.trump):hd; }
  function winner(){ let w=st.trick[0]; st.trick.forEach(x=>{ const a=x.c, b=w.c; if(a.s===st.trump&&b.s!==st.trump) w=x; else if(a.s===b.s&&R(a)>R(b)) w=x; }); return w.p; }
  function play(p,c){ if(st.trump==null) st.trump=c.s; st.hands[p].splice(st.hands[p].indexOf(c),1); st.trick.push({p,c}); st.played.push({p,c}); beep(p?340:560); if(st.trick.length<4){ st.turn=(p+1)%4; render(); if(st.turn) ctx.after(700,ai); return; }
   const w=winner(); st.msg=(w?NM[w]+' takes':'You take')+' the trick.'; render(); ctx.after(1100,()=>{ st.won[team(w)].push(...st.trick.map(x=>x.c)); st.trick=[]; st.turn=st.lead=w; if(!st.hands[0].length) return score(); render(); if(st.turn) ctx.after(700,ai); }); }
  function score(){ const tr=st.played.filter(x=>x.c.s===st.trump); const pts=[0,0], why=[]; if(tr.length){ const hi=tr.reduce((a,b)=>R(b.c)>R(a.c)?b:a), lo=tr.reduce((a,b)=>R(b.c)<R(a.c)?b:a); pts[team(hi.p)]++; why.push('High '+(team(hi.p)?'them':'us')); pts[team(lo.p)]++; why.push('Low '+(team(lo.p)?'them':'us')); }
   for(const t of [0,1]) if(st.won[t].some(c=>c.r===11&&c.s===st.trump)){ pts[t]++; why.push('Jack '+(t?'them':'us')); } const g=st.won.map(cs=>cs.reduce((a,c)=>a+gp(c),0)); if(g[0]!==g[1]){ const t=g[0]>g[1]?0:1; pts[t]++; why.push('Game '+(t?'them':'us')); }
   const bt=team(st.bidder); if(pts[bt]<st.bid){ pts[bt]=-st.bid; why.push('the bidders were set'); } st.score[0]+=pts[0]; st.score[1]+=pts[1]; st.phase='end';
   const done=st.score.some(s=>s>=+O.to); st.msg='Hand: us '+(pts[0]>=0?'+':'')+pts[0]+', them '+(pts[1]>=0?'+':'')+pts[1]+' ('+why.join(', ')+').'+(done?(st.score[0]>=st.score[1]?' You and Orion win! 🎉':' Nova and Vega win.'):''); if(done) st.over=true; render(); }
  function ai(){ if(st.phase!=='play'||!st.turn) return; const p=st.turn, L2=legal(p); let c;
   if(!st.trick.length){ const tr=st.trump; const pool=tr==null?L2:L2; const byS={}; pool.forEach(x=>(byS[x.s]=byS[x.s]||[]).push(x)); const ts=tr==null?+Object.keys(byS).sort((a,b)=>byS[b].length-byS[a].length)[0]:tr; const t=pool.filter(x=>x.s===ts).sort((a,b)=>R(b)-R(a)); c=t[0]||pool.slice().sort((a,b)=>R(b)-R(a))[0]; }
   else { const cur=winner(); const mate=team(cur)===team(p); const beat=L2.filter(x=>{ st.trick.push({p,c:x}); const w=winner()===p; st.trick.pop(); return w; }).sort((a,b)=>R(a)-R(b)); c=mate?L2.slice().sort((a,b)=>gp(b)-gp(a)||R(a)-R(b))[0]:(beat[0]||L2.slice().sort((a,b)=>R(a)-R(b))[0]); }
   play(p,c); }
  function render(){ root.innerHTML=''; const w=cw(ctx,7,60); const top=h('div',{className:'k4Row'}); [2,1,3].forEach(p=>{ const s=h('div',{className:'k4Seat'+(st.turn===p&&st.phase!=='end'?' turn':'')}); s.appendChild(h('div',null,NM[p]+(team(p)?' (them)':' (partner)')+(st.bids[p]!=null?' · bid '+(st.bids[p]||'pass'):''))); s.appendChild(backs(st.hands[p].length,Math.round(w*.4))); top.appendChild(s); }); root.appendChild(top);
   const T=h('div',{className:'k5Trick'}); st.trick.forEach(x=>{ const e=h('div',{className:'t'+x.p}); e.appendChild(cardEl(x.c,Math.round(w*.85))); T.appendChild(e); }); T.appendChild(h('div',{className:'tc'},st.trump!=null?'Trumps '+SU[st.trump]+VS:'Bid '+(st.bid||'–'))); root.appendChild(T);
   root.appendChild(h('div',{className:'k4Msg'},st.msg+' · Us '+st.score[0]+' · Them '+st.score[1]+' (to '+O.to+')'));
   const ok=st.phase==='play'&&st.turn===0?legal(0):[]; const hr=h('div',{className:'k4Hand'}); st.hands[0].slice().sort((a,b)=>a.s-b.s||R(a)-R(b)).forEach(c=>{ const e=cardEl(c,w,false,ok.includes(c)?'play':''); e.addEventListener('click',()=>{ if(ok.includes(c)) play(0,c); }); hr.appendChild(e); }); root.appendChild(hr);
   const b=bar(root); if(st.phase==='bid'&&st.turn===0){ btn(b,'Pass',()=>placeBid(0,0)); [2,3,4].filter(x=>x>st.bid).forEach(x=>btn(b,'Bid '+x,()=>placeBid(0,x),'go')); } if(st.phase==='end') btn(b,st.over?'🔁 New game':'🃏 Next hand',()=>{ if(st.over){ st.score=[0,0]; st.over=false; } deal(); },'go'); ctx.status(st.msg); }
  deal(); window.__kgst=()=>st; return {state:()=>st};
 });

 /* ───────── NEST BID (KAN-IN's own bid-for-trump game) ───────── */
 const KCN=['Red','Blue','Green','Gold'];
 const nbEl=(c,w,cls,down)=>{ const e=h('div',{className:'nb '+(down?'back':c.b?'bird':'k'+c.k)+(cls?' '+cls:''),style:'--w:'+w+'px'}); if(!down){ e.textContent=c.b?'🐦':String(c.v); if(!c.b) e.appendChild(h('small',null,KCN[c.k])); } return e; };
 const nbPts=c=>c.b?20:c.v===1?15:c.v===14||c.v===10?10:c.v===5?5:0; const nbRank=c=>c.b?100:c.v===1?15:c.v;
 G.reg('c_nest','Nest Bid',CAT,'KAN-IN’s own partnership game of bidding for trumps, played with its own deck: four colours (red, blue, green, gold) numbered 1 to 14, and the Bird. You and Orion play against Nova and Vega. Thirteen cards each; five go face down in the nest. Bid in fives from 70 for the points your side will take (or pass for good). The winner takes the nest, buries any five cards and names the trump colour. The 1 is the highest card of each colour, then 14 down to 2; the Bird is the highest trump of all and may be played at any time. Follow the colour led if you can. Points: each 1 is 15, each 14 and 10 is 10, each 5 is 5, the Bird 20, and the last trick takes the nest’s points. Make your bid or lose it; first side to the target wins.',ctx=>{
  const O=OPT(ctx,'c_nest',[['to','Play to',[[300,'300'],[500,'500 (standard)'],[700,'700'],[1000,'1,000'],[1500,'1,500']],500],['min','Lowest bid',[[50,'50'],[60,'60'],[70,'70 (standard)'],[80,'80'],[100,'100']],70]]);
  const team=p=>p%2; const st={hands:[],nest:[],bids:[],passed:[],bid:0,bidder:-1,trump:null,trick:[],turn:0,lead:0,won:[0,0],score:[0,0],dealer:3,phase:'bid',msg:'',over:false,bury:new Set(),last:-1};
  const root=h('div',{className:'k4'}); ctx.area.appendChild(root); const MIN=+O.min;
  function deal(){ const d=[]; for(let k=0;k<4;k++) for(let v=1;v<=14;v++) d.push({k,v}); d.push({b:1,k:-1,v:0}); shuffle(d); st.hands=[0,1,2,3].map(()=>d.splice(0,13)); st.nest=d; st.dealer=(st.dealer+1)%4; st.bids=[]; st.passed=[false,false,false,false]; st.bid=0; st.bidder=-1; st.trump=null; st.trick=[]; st.won=[0,0]; st.phase='bid'; st.turn=(st.dealer+1)%4; st.msg='Bidding from '+MIN+'.'; render(); if(st.turn) ctx.after(700,aiBid); }
  const est=hd=>{ let v=hd.reduce((a,c)=>a+nbPts(c),0)*0.6; for(let k=0;k<4;k++){ const n=hd.filter(c=>c.k===k).length; v+=Math.max(0,n-3)*9; } if(hd.some(c=>c.b)) v+=15; return Math.round(v+40); };
  function nextBidder(p){ for(let i=1;i<=4;i++){ const q=(p+i)%4; if(!st.passed[q]) return q; } return p; }
  function placeBid(p,b){ if(b){ st.bid=b; st.bidder=p; st.bids[p]=b; st.msg=(p?NM[p]:'You')+' bid '+b+'. '; } else { st.passed[p]=true; st.bids[p]=0; st.msg=(p?NM[p]:'You')+' pass. '; }
   const left=[0,1,2,3].filter(q=>!st.passed[q]); if(left.length===1&&st.bidder>=0||left.length===0){ if(st.bidder<0){ st.bidder=st.dealer; st.bid=MIN; } return takeNest(); } st.turn=nextBidder(p); render(); if(st.turn) ctx.after(650,aiBid); }
  function aiBid(){ if(st.phase!=='bid'||!st.turn) return; const p=st.turn; const want=est(st.hands[p]); const nb=Math.max(MIN,st.bid+5); placeBid(p,want>=nb&&nb<=180?nb:0); }
  function takeNest(){ const p=st.bidder; st.hands[p].push(...st.nest); st.nest=[]; st.phase='bury'; st.turn=p; st.msg=(p?NM[p]+' won the bid at '+st.bid+' and takes the nest.':'You won the bid at '+st.bid+': pick five cards to bury, then name trumps.'); render(); if(p) ctx.after(900,aiBury); }
  function aiBury(){ const p=st.bidder, hd=st.hands[p]; const cnt=[0,1,2,3].map(k=>hd.filter(c=>c.k===k).reduce((a,c)=>a+1+nbRank(c)/15,0)); const tr=cnt.indexOf(Math.max(...cnt)); const order=hd.filter(c=>!c.b&&c.k!==tr).sort((a,b)=>nbPts(a)-nbPts(b)||nbRank(a)-nbRank(b)); const bury=order.slice(0,5); bury.forEach(c=>hd.splice(hd.indexOf(c),1)); st.nest=bury; startPlay(tr); }
  function startPlay(tr){ st.trump=tr; st.phase='play'; st.turn=st.lead=st.bidder; st.msg='Trumps are '+KCN[tr]+'. '+(st.bidder?NM[st.bidder]+' leads.':'You lead.'); render(); if(st.turn) ctx.after(800,ai); }
  const col=c=>c.b?st.trump:c.k;
  function legal(p){ const hd=st.hands[p]; if(!st.trick.length) return hd; const led=col(st.trick[0].c); const f=hd.filter(c=>col(c)===led); return f.length?hd.filter(c=>col(c)===led||c.b):hd; }
  function winner(){ let w=st.trick[0]; st.trick.forEach(x=>{ const a=x.c, b=w.c; if(col(a)===st.trump&&col(b)!==st.trump) w=x; else if(col(a)===col(b)&&nbRank(a)>nbRank(b)) w=x; }); return w.p; }
  function play(p,c){ st.hands[p].splice(st.hands[p].indexOf(c),1); st.trick.push({p,c}); beep(p?340:560); if(st.trick.length<4){ st.turn=(p+1)%4; render(); if(st.turn) ctx.after(650,ai); return; }
   const w=winner(); const pts=st.trick.reduce((a,x)=>a+nbPts(x.c),0); st.msg=(w?NM[w]+' takes':'You take')+' the trick'+(pts?' (+'+pts+')':'')+'.'; render(); ctx.after(1100,()=>{ st.won[team(w)]+=pts; st.trick=[]; st.turn=st.lead=w; st.last=w; if(!st.hands[0].length) return score(); render(); if(st.turn) ctx.after(650,ai); }); }
  function score(){ st.won[team(st.last)]+=st.nest.reduce((a,c)=>a+nbPts(c),0); const bt=team(st.bidder); const made=st.won[bt]>=st.bid; const add=[0,0]; add[bt]=made?st.won[bt]:-st.bid; add[1-bt]=st.won[1-bt]; st.score[0]+=add[0]; st.score[1]+=add[1]; st.phase='end'; const done=st.score.some(s=>s>=+O.to); st.msg=(made?'The bid was made. ':'The bidders were set! ')+'Hand: us '+(add[0]>=0?'+':'')+add[0]+', them '+(add[1]>=0?'+':'')+add[1]+'.'+(done?(st.score[0]>=st.score[1]?' You and Orion win! 🎉':' Nova and Vega win.'):''); if(done) st.over=true; render(); }
  function ai(){ if(st.phase!=='play'||!st.turn) return; const p=st.turn, L2=legal(p); let c; if(!st.trick.length){ c=L2.slice().sort((a,b)=>(col(b)===st.trump)-(col(a)===st.trump)||nbRank(b)-nbRank(a))[0]; if(nbRank(c)<12) c=L2.slice().sort((a,b)=>nbPts(a)-nbPts(b)||nbRank(a)-nbRank(b))[0]; }
   else { const cur=winner(); const mate=team(cur)===team(p); const beat=L2.filter(x=>{ st.trick.push({p,c:x}); const ww=winner()===p; st.trick.pop(); return ww; }).sort((a,b)=>nbRank(a)-nbRank(b)); c=mate?L2.slice().sort((a,b)=>nbPts(b)-nbPts(a)||nbRank(a)-nbRank(b))[0]:(beat[0]||L2.slice().sort((a,b)=>nbPts(a)-nbPts(b)||nbRank(a)-nbRank(b))[0]); }
   play(p,c); }
  function render(){ root.innerHTML=''; const w=cw(ctx,9,54); const top=h('div',{className:'k4Row'}); [2,1,3].forEach(p=>{ const s=h('div',{className:'k4Seat'+(st.turn===p&&st.phase!=='end'?' turn':'')}); s.appendChild(h('div',null,NM[p]+(team(p)?' (them)':' (partner)')+(st.bids[p]!=null?' · '+(st.bids[p]||'pass'):''))); const r=h('div',{className:'k4Hand'}); for(let k=0;k<Math.min(st.hands[p].length,6);k++) r.appendChild(nbEl({},Math.round(w*.4),'',true)); s.appendChild(r); top.appendChild(s); }); root.appendChild(top);
   const T=h('div',{className:'k5Trick'}); st.trick.forEach(x=>{ const e=h('div',{className:'t'+x.p}); e.appendChild(nbEl(x.c,Math.round(w*.85))); T.appendChild(e); }); T.appendChild(h('div',{className:'tc'},st.trump!=null?'Trumps '+KCN[st.trump]:'Bid '+(st.bid||'–'))); root.appendChild(T);
   root.appendChild(h('div',{className:'k4Msg'},st.msg+' · This hand: us '+st.won[0]+', them '+st.won[1]+' · Score us '+st.score[0]+' · them '+st.score[1]));
   const ok=st.phase==='play'&&st.turn===0?legal(0):[]; const hr=h('div',{className:'k4Hand'}); st.hands[0].map((c,i)=>[c,i]).sort((a,b)=>(a[0].b?-1:0)-(b[0].b?-1:0)||a[0].k-b[0].k||nbRank(a[0])-nbRank(b[0])).forEach(([c,i])=>{ const e=nbEl(c,w,(st.bury.has(i)?'sel':'')+(ok.includes(c)?' play':'')); e.addEventListener('click',()=>{ if(st.phase==='bury'&&st.bidder===0){ st.bury.has(i)?st.bury.delete(i):st.bury.size<5&&st.bury.add(i); render(); } else if(ok.includes(c)) play(0,c); }); hr.appendChild(e); }); root.appendChild(hr);
   const b=bar(root); if(st.phase==='bid'&&st.turn===0&&!st.passed[0]){ btn(b,'Pass',()=>placeBid(0,0)); const nb=Math.max(MIN,st.bid+5); [nb,nb+5,nb+10,nb+20].filter(x=>x<=200).forEach(x=>btn(b,'Bid '+x,()=>placeBid(0,x),'go')); }
   if(st.phase==='bury'&&st.bidder===0){ if(st.bury.size===5){ [0,1,2,3].forEach(k=>btn(b,'Bury & trumps: '+KCN[k],()=>{ const idx=[...st.bury].sort((a,c)=>c-a); st.nest=idx.map(i=>st.hands[0].splice(i,1)[0]); st.bury=new Set(); startPlay(k); },'go')); } else b.appendChild(h('span',{className:'k4Msg'},'Bury '+(5-st.bury.size)+' more')); }
   if(st.phase==='end') btn(b,st.over?'🔁 New game':'🃏 Next hand',()=>{ if(st.over){ st.score=[0,0]; st.over=false; } deal(); },'go'); ctx.status(st.msg); }
  deal(); window.__kgst=()=>st; return {state:()=>st};
 });

 /* ───────── PINOCHLE (two-handed) ───────── */
 const PR=[9,11,12,13,10,1]; /* 9, J, Q, K, 10, A: low to high */ const prk=c=>PR.indexOf(c.r); const pPts=c=>c.r===1?11:c.r===10?10:c.r===13?4:c.r===12?3:c.r===11?2:0;
 const pName=r=>r===1?'A':r===13?'K':r===12?'Q':r===11?'J':String(r);
 function bestMeld(hd,trump,used){ /* one meld from the hand: [points, name, cards] */ const has=(r,s,n)=>hd.filter(c=>c.r===r&&c.s===s).length>=(n||1); const pick=(r,s)=>hd.find(c=>c.r===r&&c.s===s); const out=[];
  if([1,10,13,12,11].every(r=>has(r,trump))) out.push([150,'a run in trumps',[1,10,13,12,11].map(r=>pick(r,trump))]);
  [[1,100,'aces around'],[13,80,'kings around'],[12,60,'queens around'],[11,40,'jacks around']].forEach(([r,p,n])=>{ if([0,1,2,3].every(s=>has(r,s))) out.push([p,n,[0,1,2,3].map(s=>pick(r,s))]); });
  if(has(12,0,2)&&has(11,2,2)) out.push([300,'double pinochle',hd.filter(c=>(c.r===12&&c.s===0)||(c.r===11&&c.s===2))]); else if(has(12,0)&&has(11,2)) out.push([40,'pinochle',[pick(12,0),pick(11,2)]]);
  for(let s=0;s<4;s++) if(has(13,s)&&has(12,s)) out.push([s===trump?40:20,(s===trump?'royal marriage':'marriage')+' in '+SU[s]+VS,[pick(13,s),pick(12,s)]]);
  if(has(9,trump)) out.push([10,'the dix (9 of trumps)',[pick(9,trump)]]);
  return out.filter(m=>!used.has(m[1])).sort((a,b)=>b[0]-a[0])[0]||null; }
 G.reg('c_pinochle','Pinochle (two-handed)',CAT,'Two players, a 48-card deck (two each of 9, J, Q, K, 10, A in every suit; the ten ranks just under the ace). Twelve cards each; the next card turned up sets trumps. While the stock lasts, play any card to each trick; the winner of a trick may show one meld and score it (a run A-10-K-Q-J in trumps 150, aces around 100, kings around 80, queens around 60, jacks around 40, pinochle Q♠+J♦ 40 (double 300), a marriage K-Q 20 (40 in trumps), the 9 of trumps 10), then both draw. When the stock is gone you must follow suit and win the trick if you can (trump if you cannot follow). Cards taken count A 11, 10 10, K 4, Q 3, J 2, and the last trick 10. First to the target wins.',ctx=>{
  const O=OPT(ctx,'c_pinochle',[['to','Play to',[[500,'500'],[1000,'1,000 (standard)'],[1500,'1,500'],[2000,'2,000'],[250,'250 (quick)']],1000]]);
  const st={hands:[[],[]],stock:[],trump:0,turnCard:null,trick:[],lead:0,turn:0,score:[0,0],hand:[0,0],used:[new Set(),new Set()],melds:[[],[]],phase:'play',msg:'',over:false,canMeld:false};
  const root=h('div',{className:'k4'}); ctx.area.appendChild(root);
  function deal(){ const d=[]; for(let k=0;k<2;k++) for(let s=0;s<4;s++) PR.forEach(r=>d.push({r,s})); shuffle(d); st.hands=[d.splice(0,12),d.splice(0,12)]; st.turnCard=d.pop(); st.trump=st.turnCard.s; st.stock=d; st.trick=[]; st.hand=[0,0]; st.used=[new Set(),new Set()]; st.melds=[[],[]]; st.lead=st.turn=st.lead?0:1; st.phase='play'; st.canMeld=false; st.msg='Trumps are '+SU[st.trump]+VS+'. '+(st.turn?'Nova leads.':'You lead.'); render(); if(st.turn) ctx.after(800,ai); }
  const late=()=>!st.stock.length&&!st.turnCard;
  function legal(p){ const hd=st.hands[p]; if(!st.trick.length||!late()) return hd; const a=st.trick[0].c; const f=hd.filter(c=>c.s===a.s); if(f.length){ const up=f.filter(c=>prk(c)>prk(a)); return up.length?up:f; } const t=hd.filter(c=>c.s===st.trump); return t.length?t:hd; }
  function win2(a,b){ if(b.c.s===a.c.s) return prk(b.c)>prk(a.c)?b.p:a.p; return b.c.s===st.trump?b.p:a.p; }
  function play(p,c){ st.hands[p].splice(st.hands[p].indexOf(c),1); st.trick.push({p,c}); beep(p?340:560); st.canMeld=false; if(st.trick.length<2){ st.turn=1-p; render(); if(st.turn) ctx.after(700,ai); return; }
   const w=win2(st.trick[0],st.trick[1]); const pts=pPts(st.trick[0].c)+pPts(st.trick[1].c); st.hand[w]+=pts; st.msg=(w?'Nova takes':'You take')+' the trick (+'+pts+').'; render();
   ctx.after(1000,()=>{ st.trick=[]; if(!late()){ /* the winner may meld, then both draw */ if(w===1){ const m=bestMeld(st.hands[1],st.trump,st.used[1]); if(m){ st.used[1].add(m[1]); st.hand[1]+=m[0]; st.melds[1].push(m[1]+' '+m[0]); st.msg='Nova melds '+m[1]+' for '+m[0]+'. '; } } else st.canMeld=!!bestMeld(st.hands[0],st.trump,st.used[0]);
     const draw=q=>{ if(st.stock.length) st.hands[q].push(st.stock.pop()); else if(st.turnCard){ st.hands[q].push(st.turnCard); st.turnCard=null; } }; draw(w); draw(1-w); }
    if(!st.hands[0].length&&!st.hands[1].length){ st.hand[w]+=10; return finish(); } st.turn=st.lead=w; render(); if(st.turn) ctx.after(800,ai); }); }
  function finish(){ st.score[0]+=st.hand[0]; st.score[1]+=st.hand[1]; st.phase='end'; const done=st.score.some(s=>s>=+O.to); st.msg='Hand: you '+st.hand[0]+', Nova '+st.hand[1]+'.'+(done?(st.score[0]>=st.score[1]?' You win! 🎉':' Nova wins.'):''); if(done) st.over=true; render(); }
  function ai(){ if(st.phase!=='play'||st.turn!==1) return; const L2=legal(1); let c; if(!st.trick.length) c=L2.slice().sort((a,b)=>(a.s===st.trump)-(b.s===st.trump)||pPts(a)-pPts(b)||prk(a)-prk(b))[0]; else { const a=st.trick[0]; const wins=L2.filter(x=>win2(a,{p:1,c:x})===1).sort((x,y)=>prk(x)-prk(y)); c=(pPts(a.c)>=4||late())&&wins.length?wins[0]:L2.slice().sort((x,y)=>pPts(x)-pPts(y)||prk(x)-prk(y))[0]; } play(1,c); }
  function render(){ root.innerHTML=''; const w=cw(ctx,13,54); const top=h('div',{className:'k4Row'}); const s=h('div',{className:'k4Seat'+(st.turn===1?' turn':'')}); s.appendChild(h('div',null,'Nova · '+st.hand[1]+' this hand · '+st.score[1]+' total'+(st.melds[1].length?' · melded: '+st.melds[1].join(', '):''))); s.appendChild(backs(st.hands[1].length,Math.round(w*.4))); top.appendChild(s);
   const sk=h('div',{className:'k4Pile'}); if(st.turnCard) sk.appendChild(cardEl(st.turnCard,Math.round(w*.8))); sk.appendChild(h('span',null,'Stock '+st.stock.length+' · trumps '+SU[st.trump]+VS)); top.appendChild(sk); root.appendChild(top);
   const T=h('div',{className:'k4Row'}); st.trick.forEach(x=>{ const e=h('div',{className:'k4Pile'}); e.appendChild(cardEl(x.c,w)); e.appendChild(h('span',null,x.p?'Nova':'You')); T.appendChild(e); }); root.appendChild(T);
   root.appendChild(h('div',{className:'k4Msg'},st.msg+' · You '+st.hand[0]+' this hand · '+st.score[0]+' total'+(st.melds[0].length?' · melded: '+st.melds[0].join(', '):'')));
   const ok=st.phase==='play'&&st.turn===0?legal(0):[]; const hr=h('div',{className:'k4Hand'}); st.hands[0].slice().sort((a,b)=>a.s-b.s||prk(a)-prk(b)).forEach(c=>{ const e=cardEl(c,w,false,ok.includes(c)?'play':''); e.addEventListener('click',()=>{ if(ok.includes(c)) play(0,c); }); hr.appendChild(e); }); root.appendChild(hr);
   const b=bar(root); if(st.canMeld&&st.turn===0&&!st.trick.length){ const m=bestMeld(st.hands[0],st.trump,st.used[0]); if(m) btn(b,'✨ Meld '+m[1]+' (+'+m[0]+')',()=>{ st.used[0].add(m[1]); st.hand[0]+=m[0]; st.melds[0].push(m[1]+' '+m[0]); st.canMeld=false; st.msg='You meld '+m[1]+' for '+m[0]+'. Now lead.'; render(); },'go'); }
   if(st.phase==='end') btn(b,st.over?'🔁 New game':'🃏 Next hand',()=>{ if(st.over){ st.score=[0,0]; st.over=false; } deal(); },'go'); ctx.status(st.msg); }
  deal(); window.__kgst=()=>st; return {state:()=>st};
 });

 /* ───────── CANASTA and HAND AND FOOT (one engine) ───────── */
 const isWild=c=>c.j||c.r===2; const cPts=c=>c.j?50:c.r===2||c.r===1?20:c.r>=8?10:5; const red3=c=>!c.j&&c.r===3&&red(c);
 function canastaGame(ctx,mode){ const HF=mode==='hf'; const id=HF?'c_handfoot':'c_canasta';
  const O=OPT(ctx,id,[['to','Play to',HF?[[2500,'2,500'],[5000,'5,000'],[7500,'7,500'],[10000,'10,000 (standard)'],[1500,'1,500 (quick)']]:[[1500,'1,500 (quick)'],[3000,'3,000'],[5000,'5,000 (standard)'],[7500,'7,500'],[10000,'10,000']],HF?5000:5000],['out','To go out you need',HF?[['2c2d','2 clean + 2 dirty books (standard)'],['1c1d','1 clean + 1 dirty book'],['3c3d','3 clean + 3 dirty books'],['2any','2 books of any kind'],['1any','1 book of any kind']]:[['1','1 canasta (standard)'],['2','2 canastas'],['1n','1 natural canasta'],['0','Nothing special'],['3','3 canastas']],HF?'2c2d':'1']]);
  const st={hands:[[],[]],feet:[[],[]],inFoot:[false,false],melds:[{},{}],red3:[[],[]],stock:[],disc:[],frozen:false,turn:0,phase:'draw',drawn:0,sel:new Set(),score:[0,0],round:[0,0],opened:[false,false],over:false,msg:''};
  const root=h('div',{className:'k4'}); ctx.area.appendChild(root);
  const minMeld=p=>{ const s=st.score[p]; return s<0?15:s<1500?50:s<3000?90:120; };
  const books=p=>{ const M=Object.values(st.melds[p]); return {clean:M.filter(m=>m.length>=7&&!m.some(isWild)).length,dirty:M.filter(m=>m.length>=7&&m.some(isWild)).length}; };
  const canOut=p=>{ const b=books(p), o=O.out; if(HF&&!st.inFoot[p]&&st.feet[p].length) return false; if(o==='0') return true; if(o==='1n') return b.clean>=1; if(o==='2c2d') return b.clean>=2&&b.dirty>=2; if(o==='1c1d') return b.clean>=1&&b.dirty>=1; if(o==='3c3d') return b.clean>=3&&b.dirty>=3; if(o==='2any') return b.clean+b.dirty>=2; if(o==='1any') return b.clean+b.dirty>=1; return b.clean+b.dirty>=+o; };
  function deck(){ const d=[]; const n=HF?4:2; for(let k=0;k<n;k++){ for(let s=0;s<4;s++) for(let r=1;r<=13;r++) d.push({r,s}); d.push({j:1,r:0,s:0},{j:1,r:0,s:1}); } return shuffle(d); }
  function deal(){ const d=deck(); const n=HF?11:15; st.hands=[d.splice(0,n),d.splice(0,n)]; st.feet=HF?[d.splice(0,11),d.splice(0,11)]:[[],[]]; st.inFoot=[false,false]; st.melds=[{},{}]; st.red3=[[],[]]; st.round=[0,0]; st.opened=[false,false]; st.disc=[d.pop()]; while(st.disc[0].j||st.disc[0].r===2||red3(st.disc[0])){ d.unshift(st.disc.pop()); st.disc=[d.pop()]; } st.stock=d; st.frozen=false; st.turn=0; st.phase='draw'; st.sel=new Set(); st.over=false; [0,1].forEach(layRed3); st.msg='Draw two from the stock, or take the discard pile.'; render(); }
  function layRed3(p){ const hd=st.hands[p]; for(let i=hd.length-1;i>=0;i--) if(red3(hd[i])){ st.red3[p].push(hd.splice(i,1)[0]); if(st.stock.length) hd.push(st.stock.pop()); } }
  const okGroup=(cs,existing)=>{ const all=(existing||[]).concat(cs); const nat=all.filter(c=>!isWild(c)), W=all.length-nat.length; if(!nat.length) return false; if(nat.some(c=>c.r!==nat[0].r)) return false; if(nat[0].r===3) return !W&&all.length>=3; return all.length>=3&&W<=3&&W<nat.length; };
  function meldCards(p,cs){ /* add the cards to the meld of their rank */ const nat=cs.filter(c=>!isWild(c)); const r=nat.length?nat[0].r:null; const key=r!=null?r:Object.keys(st.melds[p]).find(k=>okGroup(cs,st.melds[p][k])); if(key==null) return false; const ex=st.melds[p][key]||[]; if(!okGroup(cs,ex)) return false; st.melds[p][key]=ex.concat(cs); cs.forEach(c=>st.hands[p].splice(st.hands[p].indexOf(c),1)); if(cs.some(isWild)&&st.disc.length) { } return true; }
  function checkFoot(p){ if(HF&&!st.hands[p].length&&!st.inFoot[p]&&st.feet[p].length){ st.hands[p]=st.feet[p]; st.feet[p]=[]; st.inFoot[p]=true; st.msg+=(p?' Nova':' You')+' picked up the foot.'; return true; } return false; }
  function endRound(p){ [0,1].forEach(q=>{ let s=0; Object.values(st.melds[q]).forEach(m=>{ s+=m.reduce((a,c)=>a+cPts(c),0); if(m.length>=7) s+=m.some(isWild)?300:500; }); s+=st.red3[q].length*100; if(q===p) s+=100; s-=st.hands[q].concat(st.feet[q]).reduce((a,c)=>a+cPts(c),0); st.round[q]=s; st.score[q]+=s; }); st.phase='end'; const done=st.score.some(x=>x>=+O.to); st.msg=(p?'Nova went out.':'You went out!')+' Round: you '+st.round[0]+', Nova '+st.round[1]+'.'+(done?(st.score[0]>=st.score[1]?' You win! 🎉':' Nova wins.'):''); if(done) st.over=true; render(); }
  function drawStock(p){ for(let k=0;k<2&&st.stock.length;k++) st.hands[p].push(st.stock.pop()); layRed3(p); st.phase='meld'; }
  function canTake(p){ const top=st.disc[st.disc.length-1]; if(!top||isWild(top)||(top.r===3&&!red(top))) return false; const hd=st.hands[p]; const nat=hd.filter(c=>!isWild(c)&&c.r===top.r); if(st.melds[p][top.r]&&!st.frozen) return true; if(nat.length>=2) return true; return !st.frozen&&nat.length>=1&&hd.some(isWild); }
  function takePile(p){ const top=st.disc[st.disc.length-1]; const hd=st.hands[p]; const use=[top]; const nat=hd.filter(c=>!isWild(c)&&c.r===top.r); if(st.melds[p][top.r]&&!st.frozen){ } else if(nat.length>=2) use.push(nat[0],nat[1]); else use.push(nat[0],hd.find(isWild));
   if(!st.opened[p]){ const pts=use.reduce((a,c)=>a+cPts(c),0); if(pts<minMeld(p)&&!(st.melds[p][top.r])) { /* the opening needs more points: add what the hand can */ } }
   st.disc.pop(); const pile=st.disc.splice(0); use.slice(1).forEach(c=>hd.splice(hd.indexOf(c),1)); st.melds[p][top.r]=(st.melds[p][top.r]||[]).concat(use); hd.push(...pile); st.opened[p]=true; st.frozen=false; layRed3(p); st.phase='meld'; return true; }
  function discard(p,c){ const hd=st.hands[p]; hd.splice(hd.indexOf(c),1); st.disc.push(c); if(isWild(c)) st.frozen=true; beep(p?340:560); if(!hd.length){ if(checkFoot(p)){ } else if(canOut(p)) return endRound(p); }
   if(!st.stock.length) return endRound(-1); st.turn=1-p; st.phase='draw'; st.sel=new Set(); st.msg=(p?'Nova discarded '+cn(c)+'. Your turn: draw or take the pile.':'Nova plays…'); render(); if(st.turn) ctx.after(800,ai); }
  function ai(){ if(st.phase==='end'||st.turn!==1) return; const p=1; if(canTake(p)&&st.disc.length>=3&&(st.opened[p]||st.disc.length>4)) takePile(p); else drawStock(p);
   const hd=st.hands[p]; const by={}; hd.forEach(c=>{ if(!isWild(c)&&!(c.r===3)) (by[c.r]=by[c.r]||[]).push(c); });
   const plan=Object.entries(by).filter(([r,cs])=>cs.length>=3||(st.melds[p][r]&&cs.length)); const pts=plan.reduce((a,[r,cs])=>a+cs.reduce((x,c)=>x+cPts(c),0),0);
   if(st.opened[p]||pts>=minMeld(p)){ plan.forEach(([r,cs])=>{ if(okGroup(cs,st.melds[p][r]||[])){ meldCards(p,cs.slice()); } }); if(plan.length) st.opened[p]=true;
    /* wilds go on melds that can hold them, nearest a canasta first */ hd.filter(isWild).forEach(w=>{ const k=Object.keys(st.melds[p]).sort((a,b)=>st.melds[p][b].length-st.melds[p][a].length).find(k=>okGroup([w],st.melds[p][k])&&st.melds[p][k].length<7); if(k) meldCards(p,[w]); }); }
   if(!hd.length){ if(checkFoot(p)) return ai2(); if(canOut(p)) return endRound(p); }
   ai2(); }
  function ai2(){ const p=1, hd=st.hands[p]; if(!hd.length){ if(canOut(p)) return endRound(p); return discard(p,hd[0]); } const by={}; hd.forEach(c=>(by[c.r]=by[c.r]||0,by[c.r]++)); const pick=hd.filter(c=>!isWild(c)).sort((a,b)=>(by[a.r]-by[b.r])||(a.r===3?-1:0)||(cPts(a)-cPts(b)))[0]||hd[0]; discard(p,pick); }
  function render(){ root.innerHTML=''; const w=cw(ctx,14,50); const top=h('div',{className:'k4Row'}); const s=h('div',{className:'k4Seat'+(st.turn===1?' turn':'')}); s.appendChild(h('div',null,'Nova · '+st.hands[1].length+' cards'+(HF?' · foot '+(st.inFoot[1]?'picked up':st.feet[1].length):'')+' · '+st.score[1]+' pts'+(st.red3[1].length?' · red 3s '+st.red3[1].length:''))); s.appendChild(backs(st.hands[1].length,Math.round(w*.4))); top.appendChild(s); root.appendChild(top);
   const meldRow=(p)=>{ const r=h('div',{className:'k4Row'}); Object.entries(st.melds[p]).sort((a,b)=>a[0]-b[0]).forEach(([k,m])=>{ const e=h('div',{className:'k4Meld'+(m.length>=7?' can':''),title:(m.length>=7?(m.some(isWild)?'mixed canasta':'natural canasta'):'meld')}); m.slice(0,9).forEach(c=>e.appendChild(cEl(c,Math.round(w*.5)))); if(m.length>9) e.appendChild(h('span',null,'+'+(m.length-9))); e.addEventListener('click',()=>{ if(p!==0||st.turn||st.phase!=='meld') return; const cs=[...st.sel].map(i=>st.hands[0][i]); if(cs.length&&okGroup(cs,m)){ m.push(...cs); cs.forEach(c=>st.hands[0].splice(st.hands[0].indexOf(c),1)); st.sel=new Set(); if(!st.hands[0].length){ if(checkFoot(0)) return render(); if(canOut(0)) return endRound(0); } render(); } }); r.appendChild(e); }); return r; };
   root.appendChild(meldRow(1));
   const mid=h('div',{className:'k4Row'}); const sk=h('div',{className:'k4Pile'}); sk.appendChild(cardEl({r:2,s:0},w,true)); sk.appendChild(h('span',null,'Stock '+st.stock.length)); sk.addEventListener('click',()=>{ if(!st.turn&&st.phase==='draw'){ drawStock(0); st.msg='Meld what you can, then discard.'; render(); } }); mid.appendChild(sk);
   const dp=h('div',{className:'k4Pile'}); const tc=st.disc[st.disc.length-1]; dp.appendChild(tc?cEl(tc,w):h('div',{className:'gslot',style:'width:'+w+'px;height:'+Math.round(w*1.4)+'px'})); dp.appendChild(h('span',null,'Pile '+st.disc.length+(st.frozen?' · frozen':''))); dp.addEventListener('click',()=>{ if(!st.turn&&st.phase==='draw'){ if(canTake(0)){ takePile(0); st.msg='You took the pile. Meld, then discard.'; } else st.msg='To take the pile you need a natural pair matching the top card'+(st.frozen?' (the pile is frozen)':'')+'.'; render(); } }); mid.appendChild(dp); root.appendChild(mid);
   root.appendChild(meldRow(0)); root.appendChild(h('div',{className:'k4Msg'},st.msg+' · You '+st.score[0]+' pts'+(st.red3[0].length?' · red 3s '+st.red3[0].length:'')+(HF?' · foot '+(st.inFoot[0]?'in play':st.feet[0].length+' cards waiting'):'')+' · Opening needs '+minMeld(0)));
   const hr=h('div',{className:'k4Hand'}); st.hands[0].map((c,i)=>[c,i]).sort((a,b)=>(isWild(a[0])-isWild(b[0]))||a[0].r-b[0].r).forEach(([c,i])=>{ const e=cEl(c,w,st.sel.has(i)?'sel':''); e.addEventListener('click',()=>{ if(st.turn||st.phase!=='meld') return; st.sel.has(i)?st.sel.delete(i):st.sel.add(i); render(); }); hr.appendChild(e); }); root.appendChild(hr);
   const b=bar(root); if(!st.turn&&st.phase==='draw'){ btn(b,'🂠 Draw two',()=>{ drawStock(0); st.msg='Meld what you can, then discard.'; render(); },'go'); if(canTake(0)) btn(b,'📥 Take the pile',()=>{ takePile(0); st.msg='Meld, then discard.'; render(); }); }
   if(!st.turn&&st.phase==='meld'){ const cs=[...st.sel].map(i=>st.hands[0][i]); btn(b,'🃏 Meld ('+cs.length+')',()=>{ const pts=cs.reduce((a,c)=>a+cPts(c),0); if(!st.opened[0]&&pts<minMeld(0)){ st.msg='Your first meld needs '+minMeld(0)+' points (this is '+pts+').'; return render(); } if(!meldCards(0,cs)){ st.msg='Not a legal meld: 3+ of a rank, at most 3 wild cards and more naturals than wilds.'; return render(); } st.opened[0]=true; st.sel=new Set(); if(!st.hands[0].length){ if(checkFoot(0)) return render(); if(canOut(0)) return endRound(0); } render(); },cs.length>=3?'go':''); btn(b,'🗑 Discard',()=>{ if(cs.length!==1){ st.msg='Select one card to discard.'; return render(); } if(st.hands[0].length===1&&!canOut(0)&&!(HF&&!st.inFoot[0])){ st.msg='You cannot go out yet: '+(HF?'you need your books':'you need a canasta')+'.'; return render(); } discard(0,cs[0]); }); }
   if(st.phase==='end') btn(b,st.over?'🔁 New game':'🃏 Next round',()=>{ if(st.over){ st.score=[0,0]; } deal(); },'go'); ctx.status(st.msg); }
  deal(); window.__kgst=()=>st; return {state:()=>st}; }
 G.reg('c_canasta','Canasta',CAT,'The great melding game for two, with two decks and four jokers. Jokers and 2s are wild; red 3s are bonus cards laid down at once (100 each). On your turn draw two cards, or take the whole discard pile if you can meld its top card with a natural pair from your hand (with one natural and a wild when the pile is not frozen; a wild card in the pile freezes it). Melds are three or more of a rank with more naturals than wilds and at most three wilds. Seven cards make a canasta: 500 natural, 300 mixed. Your first meld must reach 50 points (90 from 1,500, 120 from 3,000). Go out once you have a canasta: +100. Card points: jokers 50, aces and 2s 20, 8 to king 10, 4 to 7 and black 3s 5; cards left in hand count against you.',ctx=>canastaGame(ctx,'c'));
 G.reg('c_handfoot','Hand and Foot',CAT,'Canasta’s big family cousin, with four decks and jokers. You are dealt two hands of eleven: the hand you play first and the foot, which you pick up when the hand is empty. Melds, wild cards, red 3s and the discard pile work as in Canasta. Books are melds of seven: clean (no wilds, 500) or dirty (with wilds, 300). To go out you must have played your foot and made the books the rules ask for (two clean and two dirty as standard). Going out scores 100; cards left in your hand and foot count against you.',ctx=>canastaGame(ctx,'hf'));

 /* ───────── SPIT ───────── */
 G.reg('c_spit','Spit',CAT,'A two-player race. Each of you has five stockpiles (one to five cards, the top card face up) and a spit pile. When you both press Spit, a card from each spit pile starts the two centre piles. Then play as fast as you can: a top card goes on a centre pile if it is one rank higher or lower (ace and king wrap), and a stockpile top can move into an empty stockpile space. When neither of you can play, press Spit again. Whoever empties all five stockpiles first wins the round.',ctx=>{
  const O=OPT(ctx,'c_spit',[['speed','Computer speed',[[2000,'Slow'],[1400,'Relaxed'],[1000,'Normal'],[700,'Quick'],[450,'Lightning']],1000]]);
  const st={lay:[[],[]],spit:[[],[]],mid:[[],[]],sel:null,over:false,msg:'',run:false};
  const root=h('div',{className:'k4'}); ctx.area.appendChild(root); let tick=null;
  const near=(a,b)=>a&&b&&(Math.abs(a.r-b.r)===1||(a.r===1&&b.r===13)||(a.r===13&&b.r===1));
  function deal(){ const d=shuffle(L.mkDeck(true)); [0,1].forEach(p=>{ const half=d.splice(0,26); st.lay[p]=[1,2,3,4,5].map(n=>{ const pile=half.splice(0,n); pile[pile.length-1].up=true; return pile; }); st.spit[p]=half; }); st.mid=[[],[]]; st.sel=null; st.over=false; st.run=false; st.msg='Press Spit to start!'; render(); }
  function spit(){ if(st.over) return; [0,1].forEach(p=>{ if(st.spit[p].length) st.mid[p].push(st.spit[p].pop()); else if(st.spit[1-p].length) st.mid[p].push(st.spit[1-p].pop()); }); st.run=true; st.msg='Go!'; beep(700); render(); clearInterval(tick); tick=ctx.every?ctx.every(+O.speed,aiStep):setInterval(aiStep,+O.speed); }
  const topOf=pile=>pile.length?pile[pile.length-1]:null;
  function canPlayAny(p){ return st.lay[p].some(pile=>{ const c=topOf(pile); return c&&c.up&&st.mid.some(m=>near(c,topOf(m))); }); }
  function playTo(p,li,mi){ const pile=st.lay[p][li], c=topOf(pile); if(!c||!c.up||!near(c,topOf(st.mid[mi]))) return false; st.mid[mi].push(pile.pop()); if(pile.length) pile[pile.length-1].up=true; beep(p?330:600,.03); if(st.lay[p].every(x=>!x.length)){ st.over=true; st.run=false; st.msg=p?'Nova emptied every stockpile first and wins.':'You emptied every stockpile first: you win! 🎉'; } return true; }
  function aiStep(){ if(st.over||!st.run) return false; const p=1; for(let li=0;li<5;li++){ for(let mi=0;mi<2;mi++){ if(playTo(1,li,mi)){ render(); return; } } } /* fill an empty space */ const empty=st.lay[1].findIndex(x=>!x.length), from=st.lay[1].findIndex(x=>x.length>1); if(empty>=0&&from>=0){ st.lay[1][empty].push(st.lay[1][from].pop()); st.lay[1][empty][0].up=true; if(st.lay[1][from].length) st.lay[1][from][st.lay[1][from].length-1].up=true; render(); return; } if(!canPlayAny(0)&&!canPlayAny(1)){ st.run=false; st.msg='Nobody can play: press Spit!'; render(); } }
  function render(){ root.innerHTML=''; const w=cw(ctx,6,64); const row=(p)=>{ const r=h('div',{className:'k4Row'}); st.lay[p].forEach((pile,li)=>{ const e=h('div',{className:'k4Pile'+(p===0&&st.sel===li?' sel':'')}); const c=topOf(pile); e.appendChild(c?cardEl(c,w,!c.up):h('div',{className:'gslot',style:'width:'+w+'px;height:'+Math.round(w*1.4)+'px'})); e.appendChild(h('span',null,String(pile.length))); if(p===0) e.addEventListener('click',()=>{ if(st.over) return; if(st.sel!=null&&!pile.length&&st.lay[0][st.sel].length>1){ pile.push(st.lay[0][st.sel].pop()); pile[0].up=true; const src=st.lay[0][st.sel]; if(src.length) src[src.length-1].up=true; st.sel=null; return render(); } st.sel=c&&c.up?li:null; render(); }); r.appendChild(e); }); return r; };
   root.appendChild(h('div',{className:'k4Msg'},'Nova · spit pile '+st.spit[1].length)); root.appendChild(row(1));
   const mid=h('div',{className:'k4Row'}); st.mid.forEach((m,mi)=>{ const c=topOf(m); const can=st.sel!=null&&near(topOf(st.lay[0][st.sel]),c); const e=h('div',{className:'k4Pile'+(can?' can':'')}); e.appendChild(c?cardEl(c,Math.round(w*1.1)):h('div',{className:'gslot',style:'width:'+Math.round(w*1.1)+'px;height:'+Math.round(w*1.54)+'px'})); e.appendChild(h('span',null,'Centre '+(mi+1))); e.addEventListener('click',()=>{ if(st.sel!=null&&st.run){ if(playTo(0,st.sel,mi)) st.sel=null; render(); } }); mid.appendChild(e); }); root.appendChild(mid);
   root.appendChild(row(0)); root.appendChild(h('div',{className:'k4Msg'},st.msg+' · Your spit pile '+st.spit[0].length)); const b=bar(root); if(!st.over&&!st.run) btn(b,'💨 SPIT!',spit,'go'); if(st.run&&!st.over) btn(b,'💨 Spit again',()=>{ if(!canPlayAny(0)) spit(); else { st.msg='You still have a move!'; render(); } }); if(st.over) btn(b,'🔁 New game',deal,'go'); ctx.status(st.msg); }
  deal(); window.__kgst=()=>st; return {state:()=>st};
 });

 /* ───────── NERTZ ───────── */
 G.reg('c_nertz','Nertz',CAT,'Racing patience for everyone at once. You each have a Nertz pile of thirteen cards (top card face up), four work piles, and the rest of your deck as a stock you turn three at a time. The foundations in the middle are shared: anyone may start one with an ace and build it up in suit to the king. Build your work piles down in alternating colours; move cards from your Nertz pile, your waste or your work piles. Empty your Nertz pile and the round stops: everyone scores a point for every card they put on the foundations and loses two for every card left in their Nertz pile.',ctx=>{
  const O=OPT(ctx,'c_nertz',[['n','Players',[[2,'You and 1 computer'],[3,'You and 2 computers'],[4,'You and 3 computers'],[5,'You and 4 computers'],[6,'You and 5 computers']],2],['speed','Computer speed',[[2500,'Slow'],[1800,'Relaxed'],[1300,'Normal'],[900,'Quick'],[600,'Lightning']],1300],['to','Play to',[[25,'25'],[50,'50'],[100,'100 (standard)'],[150,'150'],[1,'One round']],50]]);
  const N=+O.n; const st={pl:[],found:[],sel:null,over:false,msg:'',score:Array(N).fill(0),run:false}; const root=h('div',{className:'k4'}); ctx.area.appendChild(root); let tick=null;
  function deal(){ st.pl=[]; for(let p=0;p<N;p++){ const d=shuffle(L.mkDeck(true)); const nz=d.splice(0,13); const work=[0,1,2,3].map(()=>[d.pop()]); st.pl.push({nz,work,stock:d,waste:[],played:0}); } st.found=[]; st.sel=null; st.over=false; st.run=true; st.msg='Go! Play aces to the middle and build up.'; render(); clearInterval(tick); tick=ctx.every?ctx.every(+O.speed,aiAll):setInterval(aiAll,+O.speed); }
  const top=a=>a.length?a[a.length-1]:null;
  const fOK=(c,fi)=>{ const F=fi<st.found.length?st.found[fi]:null; if(!F) return c.r===1; const t=top(F); return t.s===c.s&&c.r===t.r+1&&t.r<13; };
  const wOK=(cs,pile)=>{ const t=top(pile); if(!t) return true; return red(t)!==red(cs[0])&&cs[0].r===t.r-1; };
  function toFound(p,c){ for(let fi=0;fi<=st.found.length;fi++){ if(fOK(c,fi)){ if(fi===st.found.length) st.found.push([c]); else st.found[fi].push(c); st.pl[p].played++; beep(p?330:600,.03); return true; } } return false; }
  function take(p,src){ const P=st.pl[p]; if(src.t==='nz') return P.nz.pop(); if(src.t==='waste') return P.waste.pop(); if(src.t==='work') return P.work[src.i].splice(src.k); }
  function peek(p,src){ const P=st.pl[p]; if(src.t==='nz') return [top(P.nz)]; if(src.t==='waste') return [top(P.waste)]; if(src.t==='work') return P.work[src.i].slice(src.k); }
  function endRound(p){ st.run=false; st.over=true; clearInterval(tick); st.pl.forEach((P,q)=>{ st.score[q]+=P.played-2*P.nz.length; }); const done=st.score.some(s=>s>=+O.to); st.msg=(p?NM[p]+' called NERTZ!':'NERTZ! You emptied your pile!')+' Round: '+st.pl.map((P,q)=>NM[q]+' '+(P.played-2*P.nz.length)).join(' · ')+'.'+(done?' '+(st.score.indexOf(Math.max(...st.score))?NM[st.score.indexOf(Math.max(...st.score))]+' wins the game.':'You win the game! 🎉'):''); if(done) st.done=true; render(); }
  function aiMove(p){ const P=st.pl[p]; const srcs=[{t:'nz'},{t:'waste'}].concat(P.work.map((w,i)=>({t:'work',i,k:w.length-1}))); for(const s of srcs){ const cs=peek(p,s); if(!cs[0]) continue; if(cs.length===1&&toFound(p,cs[0])){ take(p,s); if(s.t==='work'&&!P.work[s.i].length&&P.nz.length) P.work[s.i].push(P.nz.pop()); return true; } }
   const nzc=top(P.nz); if(nzc){ for(let i=0;i<4;i++) if(wOK([nzc],P.work[i])){ P.work[i].push(P.nz.pop()); return true; } } const wc=top(P.waste); if(wc){ for(let i=0;i<4;i++) if(P.work[i].length&&wOK([wc],P.work[i])){ P.work[i].push(P.waste.pop()); return true; } }
   /* turn three */ if(P.stock.length){ for(let k=0;k<3&&P.stock.length;k++) P.waste.push(P.stock.pop()); return true; } if(P.waste.length){ P.stock=P.waste.reverse(); P.waste=[]; return true; } return false; }
  function aiAll(){ if(!st.run) return false; for(let p=1;p<N;p++){ aiMove(p); if(!st.pl[p].nz.length){ endRound(p); return false; } } render(); }
  function render(){ root.innerHTML=''; const w=cw(ctx,9,54); const opp=h('div',{className:'k4Row'}); for(let p=1;p<N;p++){ const P=st.pl[p]; opp.appendChild(h('div',{className:'k4Seat'},NM[p]+' · Nertz '+P.nz.length+' · played '+P.played+' · '+st.score[p]+' pts')); } root.appendChild(opp);
   const F=h('div',{className:'k4Row'}); st.found.forEach((f,fi)=>{ const e=h('div',{className:'k4Pile'}); e.appendChild(cardEl(top(f),Math.round(w*.8))); e.addEventListener('click',()=>tapFound(fi)); F.appendChild(e); }); const nf=h('div',{className:'k4Pile'}); nf.appendChild(h('div',{className:'gslot',style:'width:'+Math.round(w*.8)+'px;height:'+Math.round(w*1.12)+'px;display:flex;align-items:center;justify-content:center;color:#ffe94a'},'A')); nf.addEventListener('click',()=>tapFound(st.found.length)); F.appendChild(nf); root.appendChild(F);
   const P=st.pl[0]; const me=h('div',{className:'k4Row'}); const pile=(label,c,src,count)=>{ const e=h('div',{className:'k4Pile'+(st.sel&&JSON.stringify(st.sel)===JSON.stringify(src)?' sel':'')}); e.appendChild(c?cardEl(c,w):h('div',{className:'gslot',style:'width:'+w+'px;height:'+Math.round(w*1.4)+'px'})); e.appendChild(h('span',null,label+(count!=null?' '+count:''))); e.addEventListener('click',()=>tapSrc(src)); return e; };
   me.appendChild(pile('Nertz',top(P.nz),{t:'nz'},P.nz.length)); const sk=h('div',{className:'k4Pile'}); sk.appendChild(cardEl({r:2,s:0},w,true)); sk.appendChild(h('span',null,'Stock '+P.stock.length)); sk.addEventListener('click',()=>{ if(!st.run) return; if(P.stock.length){ for(let k=0;k<3&&P.stock.length;k++) P.waste.push(P.stock.pop()); } else { P.stock=P.waste.reverse(); P.waste=[]; } st.sel=null; render(); }); me.appendChild(sk); me.appendChild(pile('Waste',top(P.waste),{t:'waste'})); root.appendChild(me);
   const wk=h('div',{className:'k4Row'}); P.work.forEach((pl,i)=>{ const col=h('div',{className:'k4Pile'}); if(!pl.length) col.appendChild(h('div',{className:'gslot',style:'width:'+w+'px;height:'+Math.round(w*1.4)+'px'})); pl.forEach((c,k)=>{ const e=cardEl(c,w,false,st.sel&&st.sel.t==='work'&&st.sel.i===i&&k>=st.sel.k?'sel':''); if(k) e.style.marginTop='-'+Math.round(w*1.05)+'px'; e.addEventListener('click',ev=>{ ev.stopPropagation(); tapSrc({t:'work',i,k}); }); col.appendChild(e); }); col.addEventListener('click',()=>tapWork(i)); wk.appendChild(col); }); root.appendChild(wk);
   root.appendChild(h('div',{className:'k4Msg'},st.msg+' · You played '+P.played+' · '+st.score[0]+' pts')); const b=bar(root); if(st.over&&!st.done) btn(b,'🃏 Next round',deal,'go'); if(st.done) btn(b,'🔁 New game',()=>{ st.score=Array(N).fill(0); st.done=false; deal(); },'go'); ctx.status(st.msg); }
  function tapSrc(src){ if(!st.run) return; if(st.sel&&src.t==='work'&&st.sel.t!=='work'||st.sel&&src.t==='work'&&st.sel.t==='work'&&st.sel.i!==src.i){ return tapWork(src.i); } const cs=peek(0,src); if(!cs[0]) return; if(st.sel&&JSON.stringify(st.sel)===JSON.stringify(src)){ /* tap twice: to a foundation */ if(cs.length===1&&toFound(0,cs[0])){ take(0,src); st.sel=null; if(!st.pl[0].nz.length) return endRound(0); } st.sel=null; return render(); } st.sel=src; render(); }
  function tapWork(i){ if(!st.run||!st.sel) return; const cs=peek(0,st.sel); if(cs[0]&&wOK(cs,st.pl[0].work[i])&&!(st.sel.t==='work'&&st.sel.i===i)){ const moved=take(0,st.sel); st.pl[0].work[i]=st.pl[0].work[i].concat(Array.isArray(moved)?moved:[moved]); st.sel=null; if(!st.pl[0].nz.length) return endRound(0); } else st.sel=null; render(); }
  function tapFound(fi){ if(!st.run||!st.sel) return; const cs=peek(0,st.sel); if(cs.length===1&&cs[0]&&fOK(cs[0],fi)){ toFound(0,cs[0]); take(0,st.sel); st.sel=null; if(!st.pl[0].nz.length) return endRound(0); } else st.sel=null; render(); }
  deal(); window.__kgst=()=>st; return {state:()=>st};
 });
})();
